  def from_map(m) do
    %TopLevel{
      attendance: decode_attendance(m["attendance"]),
      clock: decode_clock(m["clock"]),
      disable_match: decode_disable_match(m["disableMatch"]),
      in_ot: decode_in_ot(m["inOT"]),
      leaddata: decode_leaddata(m["leaddata"]),
      officials_referee1: decode_officials_referee1(m["officials_referee1"]),
      officials_referee2: decode_officials_referee2(m["officials_referee2"]),
      officials_referee3: decode_officials_referee3(m["officials_referee3"]),
      othermatches: Enum.map(m["othermatches"], &Othermatch.from_map/1),
      pbp: Enum.map(m["pbp"], &Pbp.from_map/1),
      period: decode_period(m["period"]),
      period_length_overtime: decode_period_length_overtime(m["periodLengthOVERTIME"]),
      period_length_regular: decode_period_length_regular(m["periodLengthREGULAR"]),
      period_type: PerType.decode(m["periodType"]),
      periods_max: decode_periods_max(m["periodsMax"]),
      scorers: m["scorers"]
      |> Map.new(fn {key, value} -> {key, (fn value -> Enum.map(value, &Scorer.from_map/1) end).(value)} end),
      timeline: decode_timeline(m["timeline"]),
      tm: m["tm"]
      |> Map.new(fn {key, value} -> {key, Tm.from_map(value)} end),
      total_time_added: decode_total_time_added(m["totalTimeAdded"]),
      totallds: Totallds.from_map(m["totallds"]),
    }
  end

  def from_json(json) do
    json
          |> Jason.decode!()
          |> from_map()
  end

  def to_map(struct) do
    %{
      "attendance" => struct.attendance,
      "clock" => struct.clock,
      "disableMatch" => struct.disable_match,
      "inOT" => struct.in_ot,
      "leaddata" => struct.leaddata,
      "officials_referee1" => struct.officials_referee1,
      "officials_referee2" => struct.officials_referee2,
      "officials_referee3" => struct.officials_referee3,
      "othermatches" => struct.othermatches && Enum.map(struct.othermatches, &Othermatch.to_map/1),
      "pbp" => struct.pbp && Enum.map(struct.pbp, &Pbp.to_map/1),
      "period" => struct.period,
      "periodLengthOVERTIME" => struct.period_length_overtime,
      "periodLengthREGULAR" => struct.period_length_regular,
      "periodType" => PerType.encode(struct.period_type),
      "periodsMax" => struct.periods_max,
      "scorers" => struct.scorers
      |> Map.new(fn {key, value} -> {key, (fn value -> Enum.map(value, &Scorer.to_map/1) end).(value)} end),
      "timeline" => struct.timeline,
      "tm" => struct.tm
      |> Map.new(fn {key, value} -> {key, Tm.to_map(value)} end),
      "totalTimeAdded" => struct.total_time_added,
      "totallds" => Totallds.to_map(struct.totallds),
    }
  end

  def to_json(struct) do
    struct
          |> to_map()
          |> Jason.encode!()
  end
end
